trazabilidad_archivos.codigo_final:
/* === RESET === */
*, *::before, *::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
}

/* === BODY Y TIPOGRAFÍA BASE === */
body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background-color: #f4f6f9;
  color: #1a1a2e;
}

/* === HEADER === */
header {
  background-color: #1a1a2e;
  color: #ffffff;
  padding: 24px 32px;
  display: flex;
  align-items: center;
  gap: 16px;
}

header img {
  height: 40px;
  width: auto;
}

header h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.5px;
}

/* === CONTENEDOR PRINCIPAL === */
.page-wrapper {
  max-width: 1200px;
  margin: 0 auto;
  padding: 40px 24px;
}

/* === INTRODUCCIÓN === */
.intro {
  text-align: center;
  margin-bottom: 40px;
}

.intro p {
  font-size: 1.1rem;
  color: #555577;
  max-width: 600px;
  margin: 0 auto;
}

/* === GRID DE TARJETAS === */
.cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 24px;
}

/* === TARJETA INDIVIDUAL === */
.card {
  background-color: #ffffff;
  border-radius: 12px;
  padding: 24px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.12);
}

.card__flag {
  font-size: 2.5rem;
  line-height: 1;
}

.card__country {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #888aaa;
}

.card__greeting {
  font-size: 1.4rem;
  font-weight: 700;
  color: #1a1a2e;
}

.card__meaning {
  font-size: 0.9rem;
  color: #555577;
  font-style: italic;
}

/* === FOOTER === */
footer {
  text-align: center;
  padding: 24px;
  font-size: 0.8rem;
  color: #aaaacc;
  border-top: 1px solid #e0e0ee;
  margin-top: 48px;
}

/* === RESPONSIVIDAD === */
@media (max-width: 600px) {
  header {
    flex-direction: column;
    text-align: center;
    padding: 16px;
  }

  header h1 {
    font-size: 1.2rem;
  }

  .page-wrapper {
    padding: 24px 16px;
  }

  .cards-grid {
    grid-template-columns: 1fr;
  }
}
